@ParameterizedTest
@CsvSource({"A-1,2", "B-7,1"})
void quoteIsPinned(String sku, int qty) throws IOException {
    String got = LegacyPricing.quote(sku, qty);
    Path golden = Path.of("src/test/resources/golden/quote_" + sku + ".txt");
    if (System.getProperty("update.golden") != null)
        Files.writeString(golden, got);          // review the diff, then commit
    assertEquals(Files.readString(golden), got);
}

